sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here
	var attachment = new GlideSysAttachment();
	var attached = attachment.copy('sc_req_item', current.getUniqueValue(), 'sys_data_source', 'cce9d12f3b8ad69013b9202a85e45a03');
	if (attached) {
		gs.info('Attachment Copied from: ' + current.number);
		var grImp = new GlideRecord('scheduled_import_set');
		if (grImp.get('8cc029a73bcad69013b9202a85e45a90')) {
			gs.executeNow(grImp);
		}
	}

})(current, previous);
